		req.Progress = renderSprintFlowProgress(deps)
	}
	result, runErr := verifyService.Verify(runCtx, args[0], args[1], req)
	runErr = finishDurableCLICommand(durable, runErr)
	var mappedRunErr error
	if runErr != nil {
